
function DoMsg_Model_Users(){this.validUsers;this.invalidUsers;this.init=function(){this.validUsers=new Object();this.invalidUsers=new Object();}
this.checkUsername=function(username,callback){if(username.length<4){if(callback&&typeof(callback)==='function'){callback(username,false);}
return false;}
if(typeof(this.invalidUsers[username])!=='undefined'){if(callback&&typeof(callback)==='function'){callback(username,false);}
return false;}
if(typeof(this.validUsers[username])!=='undefined'){if(callback&&typeof(callback)==='function'){callback(username,true);}
return true;}
jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"checkUsername",username:username},success:function(response){if(response.result=="OK"){DoMessaging.getInstance().usersModel.validUsers[username]=true;if(callback&&typeof(callback)==='function'){callback(username,true);}}else{DoMessaging.getInstance().usersModel.invalidUsers[username]=true;if(callback&&typeof(callback)==='function'){callback(username,false);}}},error:DoMessaging.getInstance().systemError});}}
function DoMsg_Model_Status(){this.inboxUnread=null;this.inboxTotal=null;this.outboxTotal=null;this.notesCount=null;this.notesLimit=null;this.myUsername=null;this.clan=false;this.init=function(){}
this.timer=function(){this.loadData();}
this.parseInitData=function(initData){this.inboxUnread=initData.inboxUnread;this.inboxTotal=initData.inboxTotal;this.outboxTotal=initData.outboxTotal;this.notesCount=initData.notesCount;this.notesLimit=initData.notesLimit;this.myUsername=initData.myUsername;this.clan=initData.clan;DoMessaging.getInstance().statusModelUpdated(-1,-1,-1);}
this.loadData=function(){var oldInboxUnread=this.inboxUnread;var oldInboxTotal=this.inboxTotal;var oldOutboxTotal=this.outboxTotal;jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"push"},success:function(response){if(response.result=='OK'){DoMessaging.getInstance().statusModel.inboxUnread=response.inboxUnread;DoMessaging.getInstance().statusModel.inboxTotal=response.inboxTotal;DoMessaging.getInstance().statusModel.outboxTotal=response.outboxTotal;DoMessaging.getInstance().statusModel.notesCount=response.notesCount;DoMessaging.getInstance().statusModel.notesLimit=response.notesLimit;DoMessaging.getInstance().statusModel.myUsername=response.myUsername;DoMessaging.getInstance().statusModel.clan=response.clan;var inboxUnreadDiff=DoMessaging.getInstance().statusModel.inboxUnread-oldInboxUnread;var inboxTotalDiff=DoMessaging.getInstance().statusModel.inboxTotal-oldInboxTotal;var outboxTotalDiff=DoMessaging.getInstance().statusModel.outboxTotal-oldOutboxTotal;DoMessaging.getInstance().statusModelUpdated(inboxUnreadDiff,inboxTotalDiff,outboxTotalDiff);}else{DoMessaging.getInstance().systemError();}},error:DoMessaging.getInstance().systemError});}}
function DoMsg_Model_Messages(){this.inboxEntrys=new Array();this.outboxEntrys=new Array();this.inboxData=new Object();this.outboxData=new Object();this.initialInboxLoaded=false;this.initialOutboxLoaded=false;this.init=function(){}
this.getInboxEntry=function(entryId){if(this.inboxData[entryId]==null){alert('Error');return;}
return this.inboxData[entryId];}
this.addInboxEntry=function(entry){for(var i in this.inboxEntrys){if(this.inboxEntrys[i]==entry.entryId){this.inboxData[entry.entryId]=entry;return;}}
this.inboxEntrys.push(entry.entryId);this.inboxData[entry.entryId]=entry;this.inboxEntrys.sort(DoMessaging.getInstance().helperObject.numberSort).reverse();}
this.setInboxEntryRead=function(entryId,callback){var entry=this.inboxData[entryId];if(entry==null){return;}
if(entry.status!=2){return;}
jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"inboxRead",entryId:entryId},success:function(response){if(response.result=='OK'){DoMessaging.getInstance().messagesModel.inboxData[entryId]['status']=3;DoMessaging.getInstance().statusModel.inboxUnread=response.inboxUnread;if(callback&&typeof(callback)==='function'){callback();}
DoMessaging.getInstance().statusModelUpdated(1,-1,-1);}else{DoMessaging.getInstance().systemError();}},error:DoMessaging.getInstance().systemError});}
this.multiDeleteInboxEntrys=function(entryIds,callback){jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"inboxMultiDelete",entryIds:entryIds},success:function(response){if(response.result=='OK'){for(var i in entryIds){DoMessaging.getInstance().messagesModel.removeInboxEntry(entryIds[i]);}
DoMessaging.getInstance().statusModel.inboxTotal=response.inboxTotal;DoMessaging.getInstance().statusModel.inboxUnread=response.inboxUnread;if(callback&&typeof(callback)==='function'){callback();}
DoMessaging.getInstance().statusModelUpdated(-1,-1,-1);DoMessaging.getInstance().messagesModelInboxUpdated();}else{DoMessaging.getInstance().systemError();}},error:DoMessaging.getInstance().systemError});}
this.deleteInboxEntry=function(entryId,callback){var entry=this.inboxData[entryId];if(entry==null){return;}
jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"inboxDelete",entryId:entryId},success:function(response){if(response.result=='OK'){DoMessaging.getInstance().messagesModel.removeInboxEntry(entryId);DoMessaging.getInstance().statusModel.inboxTotal=response.inboxTotal;DoMessaging.getInstance().statusModel.inboxUnread=response.inboxUnread;if(callback&&typeof(callback)==='function'){callback();}
DoMessaging.getInstance().statusModelUpdated(-1,-1,-1);DoMessaging.getInstance().messagesModelInboxUpdated();}else{DoMessaging.getInstance().systemError();}},error:DoMessaging.getInstance().systemError});}
this.removeInboxEntry=function(entryId){var newEntrys=new Array();var newData=new Object();for(var i in this.inboxEntrys){var myEntryId=this.inboxEntrys[i];if(entryId==myEntryId){continue;}else{newEntrys.push(myEntryId);newData[myEntryId]=this.inboxData[myEntryId];}}
this.inboxEntrys=newEntrys;this.inboxData=newData;this.inboxEntrys.sort(DoMessaging.getInstance().helperObject.numberSort).reverse();}
this.getOutboxEntry=function(entryId){if(this.outboxData[entryId]==null){alert('Error');return;}
return this.outboxData[entryId];}
this.addOutboxEntry=function(entry){for(var i in this.outboxEntrys){if(this.outboxEntrys[i]==entry.entryId){this.outboxData[entry.entryId]=entry;return;}}
this.outboxEntrys.push(entry.entryId);this.outboxData[entry.entryId]=entry;this.outboxEntrys.sort(DoMessaging.getInstance().helperObject.numberSort).reverse();}
this.multiDeleteOutboxEntrys=function(entryIds,callback){jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"outboxMultiDelete",entryIds:entryIds},success:function(response){if(response.result=='OK'){for(var i in entryIds){DoMessaging.getInstance().messagesModel.removeOutboxEntry(entryIds[i]);}
DoMessaging.getInstance().statusModel.outboxTotal=response.outboxTotal;if(callback&&typeof(callback)==='function'){callback();}
DoMessaging.getInstance().statusModelUpdated(-1,-1,-1);DoMessaging.getInstance().messagesModelOutboxUpdated();}else{DoMessaging.getInstance().systemError();}},error:DoMessaging.getInstance().systemError});}
this.deleteOutboxEntry=function(entryId,callback){var entry=this.outboxData[entryId];if(entry==null){return;}
jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"outboxDelete",entryId:entryId},success:function(response){if(response.result=='OK'){DoMessaging.getInstance().messagesModel.removeOutboxEntry(entryId);DoMessaging.getInstance().statusModel.outboxTotal=response.outboxTotal;if(callback&&typeof(callback)==='function'){callback();}
DoMessaging.getInstance().statusModelUpdated(-1,-1,-1);DoMessaging.getInstance().messagesModelOutboxUpdated();}else{DoMessaging.getInstance().systemError();}},error:DoMessaging.getInstance().systemError});}
this.removeOutboxEntry=function(entryId){var newEntrys=new Array();var newData=new Object();for(var i in this.outboxEntrys){var myEntryId=this.outboxEntrys[i];if(entryId==myEntryId){continue;}else{newEntrys.push(myEntryId);newData[myEntryId]=this.outboxData[myEntryId];}}
this.outboxEntrys=newEntrys;this.outboxData=newData;this.outboxEntrys.sort(DoMessaging.getInstance().helperObject.numberSort).reverse();}
this.parseInboxInitData=function(initData){for(var i in initData.entrys){var entry=initData.entrys[i];DoMessaging.getInstance().messagesModel.addInboxEntry(entry);}
DoMessaging.getInstance().messagesModel.initialInboxLoaded=true;DoMessaging.getInstance().messagesModelInboxUpdated();}
this.loadInboxData=function(offset,limit,callback){jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"inboxGet",offset:offset,limit:limit},success:function(response){if(response.result=='OK'){for(var i in response.entrys){var entry=response.entrys[i];DoMessaging.getInstance().messagesModel.addInboxEntry(entry);}
if(callback&&typeof(callback)==='function'){callback();}
DoMessaging.getInstance().messagesModelInboxUpdated();}else{DoMessaging.getInstance().systemError();}},error:DoMessaging.getInstance().systemError});}
this.parseOutboxInitData=function(initData){for(var i in initData.entrys){var entry=initData.entrys[i];DoMessaging.getInstance().messagesModel.addOutboxEntry(entry);}
DoMessaging.getInstance().messagesModel.initialOutboxLoaded=true;DoMessaging.getInstance().messagesModelOutboxUpdated();}
this.loadOutboxData=function(offset,limit,callback){jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"outboxGet",offset:offset,limit:limit},success:function(response){if(response.result=='OK'){for(var i in response.entrys){var entry=response.entrys[i];DoMessaging.getInstance().messagesModel.addOutboxEntry(entry);}
if(callback&&typeof(callback)==='function'){callback();}
DoMessaging.getInstance().messagesModelOutboxUpdated();}else{DoMessaging.getInstance().systemError();}},error:DoMessaging.getInstance().systemError});}
this.send=function(parentType,parentId,recipientType,recipients,subject,body,callback,blacklistCallback,blockmessagesCallback,spammessagesCallback){jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"send",parentType:parentType,parentId:parentId,recipientType:recipientType,recipients:recipients,subject:subject,body:body},success:function(response){if(response.result=='OK'){DoMessaging.getInstance().timerTick();if(callback&&typeof(callback)==='function'){callback();}}else{if(response.blacklist&&blacklistCallback&&typeof(blacklistCallback)==='function'){if(blacklistCallback){blacklistCallback();}}
else if(response.blocked&&blockmessagesCallback&&typeof(blockmessagesCallback)==='function'){if(blockmessagesCallback){blockmessagesCallback();}}
else if(response.spam&&spammessagesCallback&&typeof(spammessagesCallback)==='function'){if(spammessagesCallback){spammessagesCallback();}}else{DoMessaging.getInstance().systemError();}}},error:DoMessaging.getInstance().systemError});}}
function DoMsg_Model_Contacts(){this.avatars=new Object();;this.requests;this.friends;this.friendIDs_base62;this.titles;this.init=function(){}
this.setAvatar=function(userHash,avatarUrl){this.avatars[userHash]=avatarUrl;}
this.addRequest=function(username){for(var i in this.requests){if(this.requests[i]==username){return;}}
this.requests.push(username);this.requests.sort();}
this.removeRequest=function(userHash){var newRequests=new Array();for(var i in this.requests){if(this.requests[i]==userHash){continue;}
newRequests.push(userHash);}
this.requests=newRequests;}
this.confirmRequest=function(userHash,callback){jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"contactsRequestConfirm",userHash:userHash},success:function(response){if(response.result=='OK'){DoMessaging.getInstance().contactsModel.removeRequest(userHash);DoMessaging.getInstance().contactsModel.addFriend(userHash);if(callback&&typeof(callback)==='function'){callback(userHash);}
DoMessaging.getInstance().contactsModelUpdated();}else{DoMessaging.getInstance().systemError();}},error:DoMessaging.getInstance().systemError});}
this.declineRequest=function(userHash,callback){jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"contactsRequestDecline",userHash:userHash},success:function(response){if(response.result=='OK'){DoMessaging.getInstance().contactsModel.removeRequest(userHash);if(callback&&typeof(callback)==='function'){callback(userHash);}
DoMessaging.getInstance().contactsModelUpdated();}else{DoMessaging.getInstance().systemError();}},error:DoMessaging.getInstance().systemError});}
this.cancelFriendship=function(userHash,callback){jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"contactsCancel",userHash:userHash},success:function(response){if(response.result=='OK'){DoMessaging.getInstance().contactsModel.removeFriend(userHash);if(callback&&typeof(callback)==='function'){callback(userHash);}
DoMessaging.getInstance().contactsModelUpdated();}else{DoMessaging.getInstance().systemError();}},error:DoMessaging.getInstance().systemError});}
this.addFriend=function(userHash){for(var i in this.friends){if(this.friends[i]==userHash){return;}}
this.friends.push(userHash);}
this.addUsernames=function(userHash,username){for(var i in this.usernames){if(this.usernames[i]==userHash){return;}}
this.usernames[userHash]=username;}
this.addTitle=function(userHash,title){for(var i in this.titles){if(this.titles[i]==userHash){return;}}
this.titles[userHash]=title;}
this.removeFriend=function(userHash){var newFriends=new Array();for(var i in this.friends){if(this.friends[i]==userHash){continue;}
newFriends.push(this.friends[i]);}
this.friends=newFriends;}
this.parseInitData=function(initData){DoMessaging.getInstance().contactsModel.requests=new Array();DoMessaging.getInstance().contactsModel.friends=new Array();DoMessaging.getInstance().contactsModel.usernames=new Array();DoMessaging.getInstance().contactsModel.titles=new Array();for(var i in initData.requests){var userHash=initData.requests[i];DoMessaging.getInstance().contactsModel.addRequest(userHash);}
for(var i in initData.friends){var userHash=initData.friends[i];DoMessaging.getInstance().contactsModel.addFriend(userHash);}
for(var i in initData.usernames){var userHash=i;var username=initData.usernames[i];DoMessaging.getInstance().contactsModel.addUsernames(userHash,username);}
for(var i in initData.titles){var userHash=i;var title=initData.titles[i];DoMessaging.getInstance().contactsModel.addTitle(userHash,title);}
for(var i in initData.avatars){var userHash=i;var avatarUrl=initData.avatars[i];DoMessaging.getInstance().contactsModel.setAvatar(userHash,avatarUrl);}
DoMessaging.getInstance().contactsModelUpdated();}
this.loadData=function(){jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"contactsGet"},success:function(response){if(response.result=='OK'){DoMessaging.getInstance().contactsModel.requests=new Array();DoMessaging.getInstance().contactsModel.friends=new Array();DoMessaging.getInstance().contactsModel.friendIDs_base62=new Array();DoMessaging.getInstance().contactsModel.titles=new Array();for(var i in response.requests){var username=response.requests[i];DoMessaging.getInstance().contactsModel.addRequest(username);}
for(var i in response.friends){var username=response.friends[i];DoMessaging.getInstance().contactsModel.addFriend(username);}
for(var i in response.friendIDs_base62){var username=i;var friendID_base62=response.friendIDs_base62[i];DoMessaging.getInstance().contactsModel.addFriendID_base62(username,friendID_base62);}
for(var i in response.titles){var username=i;var title=response.titles[i];DoMessaging.getInstance().contactsModel.addTitle(username,title);}
for(var i in initData.avatars){var username=i;var avatarUrl=initData.avatars[i];DoMessaging.getInstance().contactsModel.setAvatar(username,avatarUrl);}
DoMessaging.getInstance().contactsModelUpdated();}else{DoMessaging.getInstance().systemError();}},error:DoMessaging.getInstance().systemError});}}
