this.calcPages=function(){if(this.currentFilter=='unread'){var count=0;for(var i in DoMessaging.getInstance().messagesModel.inboxEntrys){var entryId=DoMessaging.getInstance().messagesModel.inboxEntrys[i];if(DoMessaging.getInstance().messagesModel.inboxData[entryId].status==2){count++;}}
this.inboxTotal=count;this.maxInboxPage=Math.ceil(count/15);}else if(this.currentFilter=='clan'){var count=0;for(var i in DoMessaging.getInstance().messagesModel.inboxEntrys){var entryId=DoMessaging.getInstance().messagesModel.inboxEntrys[i];if(DoMessaging.getInstance().messagesModel.inboxData[entryId].type==20){count++;}}
this.inboxTotal=count;this.maxInboxPage=Math.ceil(count/15);}else if(this.currentFilter=='system'){var count=0;for(var i in DoMessaging.getInstance().messagesModel.inboxEntrys){var entryId=DoMessaging.getInstance().messagesModel.inboxEntrys[i];if(DoMessaging.getInstance().messagesModel.inboxData[entryId].type==50){count++;}}
this.inboxTotal=count;this.maxInboxPage=Math.ceil(count/15);}else{this.inboxTotal=DoMessaging.getInstance().statusModel.inboxTotal;this.maxInboxPage=Math.ceil(DoMessaging.getInstance().statusModel.inboxTotal/15);}
this.maxOutboxPage=Math.ceil(DoMessaging.getInstance().statusModel.outboxTotal/15);}
this.updatePageSwitch=function(){var currentPage=this.currentPage;if(this.currentFolder=='inbox'){var maxPage=this.maxInboxPage;}else{var maxPage=this.maxOutboxPage;}
var showNavigation=false;if(currentPage<2){jQuery('#domsg_messages_pageLeft').addClass('button-left-disabled');}else{showNavigation=true;jQuery('#domsg_messages_pageLeft').removeClass('button-left-disabled');}
var nextPage=currentPage+1;if(nextPage>maxPage){jQuery('#domsg_messages_pageRight').addClass('button-right-disabled');}else{showNavigation=true;jQuery('#domsg_messages_pageRight').removeClass('button-right-disabled');}
var pageInfoText=DoMessaging.getInstance().translations['messaging_common_pageInfo'];var start=((currentPage-1)*15)+1;if(this.currentFolder=='inbox'){if(start>this.inboxTotal){start=this.inboxTotal;}}else{if(start>DoMessaging.getInstance().statusModel.outboxTotal){start=DoMessaging.getInstance().statusModel.outboxTotal;}}
var end=((currentPage)*15);if(this.currentFolder=='inbox'){if(end>this.inboxTotal){end=this.inboxTotal;}}else{if(end>DoMessaging.getInstance().statusModel.outboxTotal){end=DoMessaging.getInstance().statusModel.outboxTotal;}}
pageInfoText=pageInfoText.replace(/%start%/g,start);pageInfoText=pageInfoText.replace(/%end%/g,end);if(this.currentFolder=='inbox'){var total=this.inboxTotal;if(typeof(total)=='undefined'){total=0;}
pageInfoText=pageInfoText.replace(/%total%/g,total);}else{pageInfoText=pageInfoText.replace(/%total%/g,DoMessaging.getInstance().statusModel.outboxTotal);}
jQuery('#domsg_messages_pageInfo').text(pageInfoText);var navDisplay;if(showNavigation){navDisplay='block';}else{navDisplay='none';}
jQuery('#domsg_messages_pageNavigation').css('display',navDisplay);}
