if(DoMessaging.getInstance().messageWriteViewController.parentMessageId!=0){var layerId='domsg_msgwrite_errorLayer';var layerDiv=DoMessaging.getInstance().layerCreator.createErrorLayer(layerId,DoMessaging.getInstance().translations['messaging_errorLayer_replyNoRecipientSwitch_title'],DoMessaging.getInstance().translations['messaging_errorLayer_replyNoRecipientSwitch_text'],function(){jQuery('#'+layerId+'-container').remove();jQuery('#'+layerId).remove();},function(){jQuery('#'+layerId+'-container').remove();jQuery('#'+layerId).remove();});return;}
