function sendMail(){var parentType=DoMessaging.getInstance().messageWriteViewController.parentType;var parentMessageId=DoMessaging.getInstance().messageWriteViewController.parentMessageId;var recipientType=DoMessaging.getInstance().messageWriteViewController.recipientType;var recipients=DoMessaging.getInstance().messageWriteViewController.recipients;var subject=jQuery('#domsg_msgwrite_subject').val();var body=jQuery('#domsg_msgwrite_body').val();DoMessaging.getInstance().messagesModel.send(parentType,parentMessageId,recipientType,recipients,subject,body,DoMessaging.getInstance().messageWriteViewController.sendMessageSuccess,DoMessaging.getInstance().messageWriteViewController.sendMessageBlacklisted,DoMessaging.getInstance().messageWriteViewController.sendMessageBlockedmessages,DoMessaging.getInstance().messageWriteViewController.sendMessageSpammessages);}
function checkLevelLimit(){var recipientType=DoMessaging.getInstance().messageWriteViewController.recipientType;var recipients=DoMessaging.getInstance().messageWriteViewController.recipients;jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"checkLevelLimit",recipientType:recipientType,recipients:recipients},success:function(response){if(response.result=='ERROR'){if(response.levelLimitReached){jQuery('#domsg_msgwrite_body').addClass('error');var layerId='domsg_msgwrite_errorLayer';var layerDiv=DoMessaging.getInstance().layerCreator.createErrorLayer(layerId,DoMessaging.getInstance().translations['messaging_errorLayer_restrictionUnknownUser_title'],response.message,function(){jQuery('#'+layerId+'-container').remove();jQuery('#'+layerId).remove();},function(){jQuery('#'+layerId+'-container').remove();jQuery('#'+layerId).remove();});DoMessaging.getInstance().hideLoader();}}else{showReCaptcha();}}});}
function showReCaptcha(){var recipientType=DoMessaging.getInstance().messageWriteViewController.recipientType;var recipients=DoMessaging.getInstance().messageWriteViewController.recipients;jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"showReCaptcha",recipientType:recipientType,recipients:recipients},success:function(response){if(response.result=='SHOW'){var divBg=jQuery('<div />');divBg.attr('id','domsg_msgwrite_errorLayer-container');divBg.addClass('layerContainer');Recaptcha.reload();jQuery('#domessaging').append(divBg);jQuery('#reCaptcha').show();DoMessaging.getInstance().hideLoader();}else if(response.result=='ERROR'){if(response.toManyRecipients){jQuery('#reCaptcha').hide();jQuery('#domsg_msgwrite_body').addClass('error');jQuery('#recaptcha_response_field').val('');var layerId='domsg_msgwrite_errorLayer';var layerDiv=DoMessaging.getInstance().layerCreator.createErrorLayer(layerId,DoMessaging.getInstance().translations['messaging_errorLayer_tooManyRecipients_title'],DoMessaging.getInstance().translations['messaging_errorLayer_tooManyRecipients_text'],function(){jQuery('#'+layerId+'-container').remove();jQuery('#'+layerId).remove();},function(){jQuery('#'+layerId+'-container').remove();jQuery('#'+layerId).remove();});DoMessaging.getInstance().hideLoader();}}else{jQuery('#reCaptcha').hide();sendMail();}}});}
