function DoMsg_Real(){this.eventsBinded=false;this.translations;this.helperObject;this.statusModel;this.messagesModel;this.contactsModel;this.notesModel;this.blacklistModel;this.folderViewController;this.messageWriteViewController;this.contactsViewController;this.notesViewController;this.intervalTimer;this.currentView;this.init=function(){this.helperObject=new DoMsg_Helper();this.helperObject.init();this.layerCreator=new DoMsg_LayerCreator();this.showLoader();this.usersModel=new DoMsg_Model_Users();this.usersModel.init();this.statusModel=new DoMsg_Model_Status();this.statusModel.init();this.messagesModel=new DoMsg_Model_Messages();this.messagesModel.init();this.blacklistModel=new DoMsg_Model_Blacklist();this.blacklistModel.init();this.contactsModel=new DoMsg_Model_Contacts();this.contactsModel.init();this.notesModel=new DoMsg_Model_Notes();this.notesModel.init();this.folderViewController=new DoMsg_Controller_FolderView();this.folderViewController.init();this.messageWriteViewController=new DoMsg_Controller_MessageWriteView();this.messageWriteViewController.init();this.contactsViewController=new DoMsg_Controller_ContactsView();this.contactsViewController.init();this.notesViewController=new DoMsg_Controller_NotesView();this.notesViewController.init();this.bindEvents();this.timerInit();this.switchToFolderViewInbox();this.loadInitialData();}
this.loadInitialData=function(){jQuery.ajax({type:'POST',url:'/ajax/messaging.php',dataType:'json',data:{command:"init"},success:function(response){if(response.result=="OK"){DoMessaging.getInstance().initialDataLoaded(response);}else{DoMessaging.getInstance().systemError();}},error:DoMessaging.getInstance().systemError});}
this.initialDataLoaded=function(response){this.statusModel.parseInitData(response.push);this.messagesModel.parseInboxInitData(response.inboxGet);this.messagesModel.parseOutboxInitData(response.outboxGet);this.contactsModel.parseInitData(response.contactsGet);this.notesModel.parseInitData(response.notesGet);this.blacklistModel.parseInitData(response.blacklistGet);this.hideLoader();}
this.systemError=function(){DoMessaging.getInstance().hideLoader();var layerId='domsg_systemError';var layerDiv=DoMessaging.getInstance().layerCreator.createErrorLayer(layerId,DoMessaging.getInstance().translations['messaging_errorLayer_system_title'],DoMessaging.getInstance().translations['messaging_errorLayer_system_text'],function(){location.reload(true);},function(){location.reload(true);});}
this.showLoader=function(){jQuery('#loader').removeClass('hidden');}
this.hideLoader=function(){jQuery('#loader').addClass('hidden');}
this.bindEvents=function(){if(this.eventsBinded){return;}
jQuery('#domsg_tab_inbox').bind({click:this.switchToFolderViewInbox,mouseover:this.helperObject.subNavTabMouseOver,mouseout:this.helperObject.subNavTabMouseOut});jQuery('#domsg_tab_outbox').bind({click:this.switchToFolderViewOutbox,mouseover:this.helperObject.subNavTabMouseOver,mouseout:this.helperObject.subNavTabMouseOut});jQuery('#domsg_tab_contacts').bind({click:this.switchToContactsView,mouseover:this.helperObject.subNavTabMouseOver,mouseout:this.helperObject.subNavTabMouseOut});jQuery('#domsg_tab_notes').bind({click:this.switchToNotesView,mouseover:this.helperObject.subNavTabMouseOver,mouseout:this.helperObject.subNavTabMouseOut});this.eventsBinded=true;}
this.timerInit=function(){this.intervalTimer=window.setInterval(this.timerTick,30000);}
this.timerTick=function(){DoMessaging.getInstance().statusModel.timer();}
this.statusModelUpdated=function(inboxUnreadDiff,inboxTotalDiff,outboxTotalDiff){this.helperObject.subNavTabInboxInfo(this.statusModel.inboxUnread,this.statusModel.inboxTotal);this.folderViewController.statsUpdated(inboxTotalDiff,outboxTotalDiff);}
this.blacklistModelUpdated=function(){this.contactsViewController.updateBlackListView();}
this.messagesModelInboxUpdated=function(){this.folderViewController.updateInboxView();this.hideLoader();}
this.messagesModelOutboxUpdated=function(){this.folderViewController.updateOutboxView();}
this.notesModelUpdated=function(){this.notesViewController.updateView();}
this.contactsModelUpdated=function(){this.contactsViewController.updateView();this.messageWriteViewController.updateContactsView();}
this.switchView=function(newView){if(newView!='folderView'&&newView!='messageWriteView'&&newView!='contactsView'&&newView!='notesView'){return;}
if(newView==this.currentView){return;}
switch(newView){case'folderView':this.messageWriteViewController.hide();this.contactsViewController.hide();this.notesViewController.hide();this.folderViewController.show();this.currentView=newView;break;case'messageWriteView':this.folderViewController.hide();this.contactsViewController.hide();this.notesViewController.hide();this.messageWriteViewController.show();this.currentView=newView;break;case'contactsView':this.folderViewController.hide();this.messageWriteViewController.hide();this.notesViewController.hide();this.contactsViewController.show();this.currentView=newView;break;case'notesView':this.folderViewController.hide();this.messageWriteViewController.hide();this.contactsViewController.hide();this.notesViewController.show();this.currentView=newView;break;}}
this.switchToFolderViewInbox=function(){DoMessaging.getInstance().folderViewController.switchFolder('inbox');DoMessaging.getInstance().switchView('folderView');}
this.switchToFolderViewOutbox=function(){DoMessaging.getInstance().folderViewController.switchFolder('outbox');DoMessaging.getInstance().switchView('folderView');}
this.switchToMessageWriteView=function(){DoMessaging.getInstance().switchView('messageWriteView');}
this.switchToContactsView=function(){DoMessaging.getInstance().switchView('contactsView');}
this.switchToNotesView=function(){DoMessaging.getInstance().switchView('notesView');}
this.setTranslations=function(jsTranslations){this.translations=jsTranslations;}}
